longsword.spec:
{"nameKo":"롱소드","nameEn":"Longsword","desc":"중세 말 독일 검객들이 익히던 양손 장검.
리히테나워는 그 비결을 수수께끼 같은 시로 남겼다.","grip":"two-hand","material":"steel","hiltLength":0.13,"bladeLength":1.05,"gripAlong":-0.14,"partMesh":"(idx, isBlade, shape, color, matOpts, look, tier) => {
    const F = finishOf(tier);
    if (isBlade) {
      if (o.bladeMesh) return o.bladeMesh(shape, color, matOpts);
      if (shape[0] !== 'box') return undefined;
      const [, hx, hy, hz] = shape;
      const mat = new THREE.MeshStandardMaterial({
        color,
        vertexColors: true,
        roughness: F.blade,
        metalness: F.metal,
        envMap: weaponEnv(),
        envMapIntensity: F.env,
        side: THREE.DoubleSide,
        ...(F.sheen ? { emissive: F.sheen, emissiveIntensity: 0.06 } : {}),
      });
      const m = new THREE.Mesh(bladeGeometry(hx, hy, hz, o.blade), mat);
      m.castShadow = true;
      return m;
    }
    const metalColor = o.metal ?? look?.hilt ?? 0x9aa3ad;
    if (idx === 0 && shape[0] === 'box' && o.grip) {
      const [, hx, hy, hz] = shape;
      return gripMesh(hx, hy, hz, o.grip.color ?? color, o.grip.style ?? 'leather', F, o.pommel?.color ?? metalColor);
    }
    if (idx === 1 && shape[0] === 'ball' && o.pommel) return pommelMesh(shape[1], o.pommel.color ?? color, o.pommel.style ?? 'wheel', F);
    if (idx === 2 && o.guard) return guardMesh(shape, o.guard.color ?? color, o.guard.style ?? 'bar', F);
    return undefined;
  }","buildParts":"buildParts(look) {
    const L = this.bladeLength;
    const grip = boxInertia(0.16, 0.018, 0.1, 0.018);
    const pommel = sphereInertia(0.418, 0.03);
    const cross = boxInertia(0.18, 0.11, 0.015, 0.022);
    const blade = bladeInertia(0.842, L, 0.344, 0.253, 0.048, 0.016);
    return [
      partTuple(['box', 0.018, 0.1, 0.018], 0, 0.16, 0, grip.Ie, grip.It, look.grip),
      partTuple(['ball', 0.03], -0.12, 0.418, 0, pommel.Ie, pommel.It, look.hilt),
      partTuple(['box', 0.11, 0.015, 0.022], 0.115, 0.18, 0, cross.Ie, cross.It, look.hilt),
      partTuple(['box', 0.024, L / 2, 0.008], 0.13 + L / 2, 0.842, blade.comY, blade.Ie, blade.It, 0xd8dde3, true),
    ];
  }","id":"longsword","edged":true,"mCut":1,"mThrust":1,"mBlunt":1,"tier":"common","power":1,"durability":0.8,"fragility":0.056,"breakChance":"breakChance(J) { return breakChance(J, this.fragility, this.material); }","breakAt":0.5,"fragile":true,"ignoreArmor":false,"thrustStyle":null,"spike":false,"breakY":null,"twoHand":true,"oneHandStance":false,"soundMaterial":"steel","controlOverrides":{"maxAimTorque":26},"capFromGrip":true,"frame":"two","style":"versatile"}

zweihander.spec:
{"nameKo":"츠바이핸더 (대형 양손검)","nameEn":"Zweihänder","desc":"두 배 급료를 받고 창 숲 맨 앞을 깨던 용병의 칼.
느리지만 맞으면 묵직하게 부순다.","grip":"two-hand","material":"steel","tier":"common","hiltLength":0.145,"bladeLength":1.215,"gripAlong":-0.24,"mCut":1.1,"mThrust":0.85,"mBlunt":1.15,"partMesh":"(idx, isBlade, shape, color, matOpts, look, tier) => {
    const F = finishOf(tier);
    if (isBlade) {
      if (o.bladeMesh) return o.bladeMesh(shape, color, matOpts);
      if (shape[0] !== 'box') return undefined;
      const [, hx, hy, hz] = shape;
      const mat = new THREE.MeshStandardMaterial({
        color,
        vertexColors: true,
        roughness: F.blade,
        metalness: F.metal,
        envMap: weaponEnv(),
        envMapIntensity: F.env,
        side: THREE.DoubleSide,
        ...(F.sheen ? { emissive: F.sheen, emissiveIntensity: 0.06 } : {}),
      });
      const m = new THREE.Mesh(bladeGeometry(hx, hy, hz, o.blade), mat);
      m.castShadow = true;
      return m;
    }
    const metalColor = o.metal ?? look?.hilt ?? 0x9aa3ad;
    if (idx === 0 && shape[0] === 'box' && o.grip) {
      const [, hx, hy, hz] = shape;
      return gripMesh(hx, hy, hz, o.grip.color ?? color, o.grip.style ?? 'leather', F, o.pommel?.color ?? metalColor);
    }
    if (idx === 1 && shape[0] === 'ball' && o.pommel) return pommelMesh(shape[1], o.pommel.color ?? color, o.pommel.style ?? 'wheel', F);
    if (idx === 2 && o.guard) return guardMesh(shape, o.guard.color ?? color, o.guard.style ?? 'bar', F);
    return undefined;
  }","buildParts":"buildParts(look) {
    const L = this.bladeLength;
    // 자루: 코등이 밑에서 폼멜(ZW.pommelY)까지 — 중간(기본) 0.115 → −0.25 (0.365 m) · 날밑 꼴 0.07 → −0.31 · 아침 꼴 ±0.16. 부품 질량은 그대로(합 2.9 kg)
    //  날밑: 가운데 ZW.crossY · 칼날: 손 위 ZW.hilt 부터 — 칼날 질량 분포(무게중심 자리·그 둘레 관성)는 모든 꼴이 같다 (위 ZW 머리말)
    const grip = boxInertia(0.26, 0.02, ZW.gripH, 0.02);
    const pommel = sphereInertia(0.62, 0.038);
    const cross = boxInertia(0.32, 0.14, 0.02, 0.026);
    const blade = bladeInertia(1.7, L, ZW.com, ZW.gyr, 0.056, 0.018);
    return [
      partTuple(['box', 0.02, ZW.gripH, 0.02], ZW.gripY, 0.26, 0, grip.Ie, grip.It, look.grip),
      partTuple(['ball', 0.038], ZW.pommelY, 0.62, 0, pommel.Ie, pommel.It, look.hilt),
      partTuple(['box', 0.14, 0.02, 0.026], ZW.crossY, 0.32, 0, cross.Ie, cross.It, look.hilt),
      partTuple(['box', 0.028, L / 2, 0.009], this.hiltLength + L / 2, 1.7, blade.comY, blade.Ie, blade.It, 0xd8dde3, true),
    ];
  }","decorate":"decorate(group, look) {
    const mat = metalMat(look.hilt, { rough: 0.34 });
    const base = this.hiltLength;
    const ricY = base + 0.02;
    const leather = new THREE.MeshStandardMaterial({ color: 0x4a2f1c, roughness: 0.9 });
    const wrap = addMesh(group, new THREE.BoxGeometry(0.06, 0.1, 0.022), leather, [0, ricY + 0.06, 0]);
    wrap.castShadow = true;
    for (const s of [-1, 1]) {
      const hook = addMesh(group, new THREE.ConeGeometry(0.008, 0.04, 8), mat, [s * 0.045, ricY + 0.13, 0]);
      hook.rotation.z = -s * 0.9; // 코등이 평면(x) 바깥으로, 칼끝 쪽으로 비스듬히
      hook.castShadow = true;
    }
  }","id":"zweihander","edged":true,"power":1,"durability":0.8,"fragility":0.056,"breakChance":"breakChance(J) { return breakChance(J, this.fragility, this.material); }","breakAt":0.5,"fragile":true,"ignoreArmor":false,"thrustStyle":null,"spike":false,"breakY":null,"twoHand":true,"oneHandStance":false,"soundMaterial":"steel","controlOverrides":{"maxAimTorque":26},"capFromGrip":true,"frame":"heavy","style":"cut"}

estoc.spec:
{"nameKo":"에스톡 (찌르기검)","nameEn":"Estoc","desc":"판금 갑옷의 틈을 찌르려 날 대신 끝을 벼린 칼.
찌르기로 싸워야 제값을 한다.","grip":"hand-and-half","material":"steel","hiltLength":0.14,"bladeLength":1.15,"gripAlong":-0.15,"mCut":0.55,"mThrust":1.35,"mBlunt":0.9,"thrustStyle":{"recover":0.7,"reach":0.12,"gap":0.5,"window":0.1},"partMesh":"(idx, isBlade, shape, color, matOpts, look, tier) => {
    const F = finishOf(tier);
    if (isBlade) {
      if (o.bladeMesh) return o.bladeMesh(shape, color, matOpts);
      if (shape[0] !== 'box') return undefined;
      const [, hx, hy, hz] = shape;
      const mat = new THREE.MeshStandardMaterial({
        color,
        vertexColors: true,
        roughness: F.blade,
        metalness: F.metal,
        envMap: weaponEnv(),
        envMapIntensity: F.env,
        side: THREE.DoubleSide,
        ...(F.sheen ? { emissive: F.sheen, emissiveIntensity: 0.06 } : {}),
      });
      const m = new THREE.Mesh(bladeGeometry(hx, hy, hz, o.blade), mat);
      m.castShadow = true;
      return m;
    }
    const metalColor = o.metal ?? look?.hilt ?? 0x9aa3ad;
    if (idx === 0 && shape[0] === 'box' && o.grip) {
      const [, hx, hy, hz] = shape;
      return gripMesh(hx, hy, hz, o.grip.color ?? color, o.grip.style ?? 'leather', F, o.pommel?.color ?? metalColor);
    }
    if (idx === 1 && shape[0] === 'ball' && o.pommel) return pommelMesh(shape[1], o.pommel.color ?? color, o.pommel.style ?? 'wheel', F);
    if (idx === 2 && o.guard) return guardMesh(shape, o.guard.color ?? color, o.guard.style ?? 'bar', F);
    return undefined;
  }","buildParts":"buildParts(look) {
    const L = this.bladeLength;
    const grip = boxInertia(0.14, 0.019, 0.12, 0.019);
    // 균형 재분배: 무승부투성이(13/24)의 근본 원인이 굼뜬 칼끝(칼날 0.84kg, 손 기준 관성 ~0.40)이라,
    // 총중량(1.6kg)은 지키고 칼날을 가볍게 해 그 몫을 폼멜로 옮긴다 — 실물 에스톡도 좁은 단면
    // 칼날에 유난히 큰 폼멜로 손 쪽에 균형을 모은 물건이다.
    const pommel = sphereInertia(0.6, 0.032);
    const cross = boxInertia(0.14, 0.1, 0.015, 0.02);
    const blade = bladeInertia(0.72, L, 0.42, 0.27, 0.022, 0.022); // 각진(사각/육각) 단면: 폭≈두께
    return [
      partTuple(['box', 0.019, 0.12, 0.019], 0, 0.14, 0, grip.Ie, grip.It, look.grip),
      partTuple(['ball', 0.032], -0.13, 0.6, 0, pommel.Ie, pommel.It, look.hilt),
      partTuple(['box', 0.1, 0.015, 0.02], 0.125, 0.14, 0, cross.Ie, cross.It, look.hilt),
      partTuple(['box', 0.011, L / 2, 0.011], 0.14 + L / 2, 0.72, blade.comY, blade.Ie, blade.It, 0xc7ccd2, true),
    ];
  }","id":"estoc","edged":true,"tier":"common","power":1,"durability":0.8,"fragility":0.056,"breakChance":"breakChance(J) { return breakChance(J, this.fragility, this.material); }","breakAt":0.5,"fragile":true,"ignoreArmor":false,"spike":false,"breakY":null,"twoHand":true,"oneHandStance":false,"soundMaterial":"steel","controlOverrides":{"maxAimTorque":22},"capFromGrip":true,"frame":"two","style":"thrust"}

