{"nameKo":"엑스칼리버","nameEn":"Excalibur","desc":"일단은 왕의 검 엑스칼리버, 라고 쓰여 있다.","grip":"two-hand","material":"steel","tier":"common","finishTier":"legend","hiltLength":0.13,"bladeLength":1,"gripAlong":-0.15,"partMesh":"(idx, isBlade, shape, color, matOpts, look, tier) => {
    const F = finishOf(tier);
    if (isBlade) {
      if (o.bladeMesh) return o.bladeMesh(shape, color, matOpts);
