뽑는 동작이 곧 베기다.","grip":"two-hand","material":"steel","school":"japanese","frame":"two","style":"versatile","tier":"common","strayPick":false,"hiltLength":0.075,"bladeLength":0.71,"gripAlong":-0.2,"mCut":1.2,"mThrust":0.9,"mBlunt":0.95,"partMesh":"(idx, isBlade, shape, color, matOpts, look, tier) => {
    const F = finishOf(tier);
    if (isBlade) {
      if (o.bladeMesh) return o.bladeMesh(shape, color, matOpts);
      if (shape[0] !== 'box') return undefined;
      const [, hx, hy, hz] = shape;
      const mat = new THREE.MeshStandardMaterial({
        color,
        vertexColors: true,
        roughness: F.blade,
        metalness: F.metal,
        envMap: weaponEnv(),
        envMapIntensity: F.env,
        side: THREE.DoubleSide,
        ...(F.sheen ? { emissive: F.sheen, emissiveIntensity: 0.06 } : {}),
      });
      const m = new THREE.Mesh(bladeGeometry(hx, hy, hz, o.blade), mat);
      m.castShadow = true;
      return m;
    }
    const metalColor = o.metal ?? look?.hilt ?? 0x9aa3ad;
    if (idx === 0 && shape[0] === 'box' && o.grip) {
      const [, hx, hy, hz] = shape;
      return gripMesh(hx, hy, hz, o.grip.color ?? color, o.grip.style ?? 'leather', F, o.pommel?.color ?? metalColor);
    }
    if (idx === 1 && shape[0] === 'ball' && o.pommel) return pommelMesh(shape[1], o.pommel.color ?? color, o.pommel.style ?? 'wheel', F);
    if (idx === 2 && o.guard) return guardMesh(shape, o.guard.color ?? color, o.guard.style ?? 'bar', F);
    return undefined;
  }","buildParts":"buildParts(look) {
    const L = this.bladeLength;
    const grip = boxInertia(0.26, 0.014, 0.15, 0.017); // 츠카: 츠바 아랫면(0.065) ~ 카시라 윗면(−0.235)
    const pommel = sphereInertia(0.06, 0.014); // 카시라
    const cross = boxInertia(0.12, 0.04, 0.005, 0.04); // 츠바 (커먼 철 츠바라 모노호시자오보다 무겁다)
    const blade = bladeInertia(0.66, L, 0.4, 0.26, 0.03, 0.007);
    return [
      partTuple(['box', 0.014, 0.15, 0.017], -0.085, 0.26, 0, grip.Ie, grip.It, look.grip),
      partTuple(['ball', 0.014], -0.245, 0.06, 0, pommel.Ie, pommel.It, look.hilt),
      partTuple(['box', 0.04, 0.005, 0.04], 0.07, 0.12, 0, cross.Ie, cross.It, look.hilt),
      partTuple(['box', 0.015, L / 2, 0.0035], this.hiltLength + L / 2, 0.66, blade.comY, blade.Ie, blade.It, 0xc9d1d6, true),
    ];
  }","decorate":"decorate(group) {
    const iron = metalMat(0x2b2e33, { rough: 0.45 });
    const copper = metalMat(0xa0623a, { rough: 0.35 });
    const habaki = addMesh(group, new THREE.BoxGeometry(0.034, 0.03, 0.011), copper, [0, this.hiltLength + 0.012, 0]);
    habaki.castShadow = true;
    const silk = new THREE.MeshStandardMaterial({ color: 0x1b1d2e, roughness: 0.85 });
    const fuchi = addMesh(group, new THREE.CylinderGeometry(0.0148, 0.0148, 0.008, 14), iron, [0, 0.061, 0]);
    fuchi.scale.z = 1.2;
    addTsukaIto(group, silk, -0.215, 0.03); // 모노호시자오와 같은 끈 — 카시라 위 −0.215 부터 후치 밑 0.03 까지 여덟 줄 (끈 32 · 매듭 16 상자가 메쉬 하나)
  }","id":"uchigatana","edged":true,"power":1,"durability":0.8,"fragility":0.056,"breakChance":"breakChance(J) { return breakChance(J, this.fragility, this.material); }","breakAt":0.5,"fragile":true,"ignoreArmor":false,"thrustStyle":null,"spike":false,"breakY":null,"twoHand":true,"oneHandStance":false,"soundMaterial":"steel","controlOverrides":{"maxAimTorque":26},"capFromGrip":true}

