  const m=new T.Mesh(geo,new T.MeshStandardMaterial({color,roughness:.97,metalness:0,side:T.DoubleSide}));
  m.name=name;m.castShadow=true;group.add(m);return m;
 };
 const shell=(levels,shape)=>{
  const p=[],ix=[];
